<?php
defined('ABSPATH')||exit; class CFP_Frontend{public function hooks():void{add_shortcode('conversionflow_step',array($this,'shortcode')); add_action('wp_enqueue_scripts',array($this,'assets'));} public function assets():void{ if(is_page()&&get_post_meta(get_the_ID(),'_cfp_funnel_id',true)){wp_enqueue_style('cfp-frontend',CFP_URL.'assets/css/frontend.css',array(),CFP_VERSION); wp_enqueue_script('cfp-frontend',CFP_URL.'assets/js/frontend.js',array(),CFP_VERSION,true);} } public function shortcode(array $atts):string{$type=sanitize_key($atts['type']??'landing'); return '<div class="cfp-step cfp-step-'.esc_attr($type).'">'.esc_html__('Design this funnel step with Elementor widgets from ConversionFlow Pro.','conversionflow-pro').'</div>';}}
